import re

from taf.sbts.oam.coam.admin import admin

from taf.ul.bts_components import Rmod as RmodComponent

from taf.ul.kpi_selector.utilities.wft.wft import WFT
from taf.ul.kpi_selector.btss.exceptions import MissingObjectError
from taf.ul.kpi_selector.utilities.kpi_logger import log_env_state, log_input_and_output
from taf.ul.kpi_selector.utilities.decorators import retry_for_scm_flag
from taf.ul.kpi_selector.utilities.SCF.SCF import get_radio_protocol_from_scf


class Rmod(object):
    """
    Representation of Rmod parameters. Gets all necessary parameters from Rmod and test line configuration file
    to set proper timeout for operations.
    """

    _connection = 'admin_connection_kpi_selector'

    def __init__(self, rmod, parent_smods, init_id):
        self.radio_type = rmod.radio_type
        self.serial_number = rmod.serial_number
        self.init_id = init_id
        self._admin = admin()
        self._wft_instance = WFT()
        self._rmod_instance = RmodComponent()
        self._id = None
        self._config = rmod
        self._parent_smods = parent_smods
        self._target_sw_version = None
        self._current_sw_version = None
        self._protocol = None
        self._scm_flag = None
        self._is_target_bd_sw_version_different = None

    def __str__(self):
        return "Rmod with serial: {} and type: {}".format(self.serial_number, self.radio_type)

    @property
    def id(self):
        """
        Returns index of rmod, e.g. "2"
        """
        if self._id is None:
            for rmods_type, rmods_info in self._admin.get_bts_info(connection=self._connection)['radioModules'].items():
                rmod_id = self._get_rmod_id(rmods_info)
                if rmod_id:
                    self._id = rmod_id
                    break
            else:
                raise MissingObjectError("Could not match rmod with serial number {} with any rmod available via "
                                         "admin.".format(self.serial_number))

        return self._id

    @property
    def protocol(self):
        """
        Returns protocol for rmod, e.g. "CPRI"
        """
        if self._protocol is None:
            self._admin.get_current_scf_file(local_dir_path="/tmp", file_name="current.xml",
                                             timeout=30, connection=self._connection)
            self._protocol = get_radio_protocol_from_scf("/tmp/current.xml", self.id)

        log_env_state("Detected protocol: {}".format(self._protocol))

        return self._protocol

    @property
    def target_sw_version(self):
        """
        Returns target sw_version of rmod, e.g. ["RF.5GL3.trunk.20210921.011"]
        """
        if self._target_sw_version is None:
            self._target_sw_version = []
            for smod_index, smod in enumerate(self._parent_smods, start=1):
                test_pc_alias = 'KPI_TestPC_of_SMOD_{0}'.format(smod_index)
                smod_alias = 'KPI_SMOD_{0}'.format(smod_index)

                try:
                    smod.connect_to_smod_via_its_test_pc(test_pc_alias, smod_alias)
                    self._target_sw_version.append(smod.get_rfsw_from_targetbd(self.radio_type, self.protocol))

                finally:
                    smod.close_connections(test_pc_alias)

        log_env_state("RMOD sw version from targetBD: {}".format(self._target_sw_version))

        return self._target_sw_version

    @property
    def scm_flag(self):
        """
        Returns scm flag for rmod, e.g. "erm6"
        """
        if self._scm_flag is None:
            sw_version_without_suffix = re.sub(r"T.$", "", self.current_sw_version)
            self._scm_flag = self._get_scm_flag(sw_version_without_suffix)

        return self._scm_flag

    @property
    def current_sw_version(self):
        """
        Returns sw_version of rmod read via admin, e.g. "RF.5GL3.trunk.20210921.011"
        """
        if self._current_sw_version is None:
            self._current_sw_version = self._get_sw_version_via_admin()

        log_env_state("RMOD sw version from admin: {}".format(self._current_sw_version))

        return self._current_sw_version

    @property
    def is_target_bd_sw_version_different(self):
        """
        Checks if rmod sw version collected from target bd is different than sw version collected
        directly from rmod unit.
        :return: True if sw versions differ, False otherwise
        :rtype: bool
        """
        if self._is_target_bd_sw_version_different is None:
            if len(set(self.target_sw_version)) > 1:
                self._is_target_bd_sw_version_different = True
            else:
                self._is_target_bd_sw_version_different = not self.target_sw_version[0] == self.current_sw_version

        log_env_state("Is rmod software version collected from targetBD different than version"
                      " from radio unit: {}".format(self._is_target_bd_sw_version_different))

        return self._is_target_bd_sw_version_different

    @log_input_and_output
    @retry_for_scm_flag(2)
    def _get_scm_flag(self, version_without_suffix):
        return self._wft_instance.get_scm_flag(version_without_suffix)

    @log_input_and_output
    def _get_sw_version_via_admin(self):
        rmod_info = []
        for hw_type in ["RMOD", "ASIRMOD"]:
            rmod_info.extend(self._admin.get_parameters_for_all(class_name=hw_type, connection=self._connection))

        for info in rmod_info:
            if str(self.serial_number) == info["serialNumber"]:
                return info["buildVersion"]

        raise MissingObjectError("Could not find sw version for rmod with serial number: {} via "
                                 "admin.".format(self.serial_number))

    @log_input_and_output
    def _get_rmod_id(self, rmods_info):
        for rmod_info in rmods_info:
            if rmod_info['serialNumber'] == self.serial_number:
                return rmod_info["id"]["configuration"].split('-')[-1]
